import * as T from './vendor/three.module.min.js';
export const SHORTCUTS=[{id:'garden',name:'גן סודי',start:.12,end:.27,side:-1,color:'#e893db',width:5.4,entryX:-7.8,exitX:-5.4},{id:'alley',name:'סמטת הספינים',start:.39,end:.53,side:1,color:'#f6b85f',width:5.2,entryX:7.8,exitX:5.4}];
export function makeShortcuts(track){return SHORTCUTS.map(spec=>{const start=spec.start*track.length,end=spec.end*track.length,a=track.at(start,spec.entryX),b=track.at(end,spec.exitX);const curve=new T.CatmullRomCurve3([a.p,a.p.clone().addScaledVector(a.t,13),a.p.clone().lerp(b.p,.47),b.p.clone().addScaledVector(b.t,-13),b.p],false,'catmullrom',.3);const length=curve.getLength();
 function at(distance,x=0){const u=Math.max(0,Math.min(1,distance/length)),p=curve.getPointAt(u),t=curve.getTangentAt(u).normalize(),right=new T.Vector3(-t.z,0,t.x).normalize();p.addScaledVector(right,x);return{p,t,right};}
 function bend(distance){const a=at(distance).t,b=at(Math.min(length,distance+2)).t;return Math.atan2(a.z*b.x-a.x*b.z,a.dot(b))/2;}
 return{...spec,start,end,length,curve,at,bend};});}
export function racerFrame(track,r,ahead=0){const route=r.routeId&&track.shortcuts.find(p=>p.id===r.routeId);return route?route.at(Math.min(route.length,r.routeDistance+ahead),r.x):track.at(r.s+ahead,r.x);}
export function routeBend(track,r){const route=r.routeId&&track.shortcuts.find(p=>p.id===r.routeId);return route?route.bend(r.routeDistance):track.bend(r.s);}
export function buildShortcuts(parent,track,box,label,mat){
 for(const route of track.shortcuts){const positions=[],indices=[];for(let i=0;i<=100;i++){for(const side of [-1,1]){const p=route.at(i/100*route.length,side*route.width/2).p;positions.push(p.x,p.y+.13,p.z);}if(i<100){const n=i*2;indices.push(n,n+1,n+2,n+1,n+3,n+2);}}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.setIndex(indices);geo.computeVertexNormals();const path=new T.Mesh(geo,new T.MeshStandardMaterial({color:route.id==='garden'?'#c099af':'#bd9c71',side:T.DoubleSide,roughness:1}));path.receiveShadow=true;parent.add(path);
  for(let d=7;d<route.length-7;d+=4){const {p,t}=route.at(d);const tile=box(parent,route.width-.4,.12,3.2,route.id==='garden'?'#edc8d7':'#f1d6a8',p.x,p.y+.1,p.z);tile.rotation.y=Math.atan2(t.x,t.z);for(const side of [-1,1]){const e=route.at(d,side*(route.width/2+.35)).p;const gem=new T.Mesh(new T.OctahedronGeometry(.26),new T.MeshBasicMaterial({color:route.color}));gem.position.copy(e);gem.position.y+=.75;parent.add(gem);}}
  // Leafy entrance conceals the branch until you notice the colored stones and question mark.
  const entrance=new T.Group(),a=route.at(0);entrance.position.copy(a.p);entrance.rotation.y=Math.atan2(a.t.x,a.t.z);parent.add(entrance);for(const x of [-3.1,3.1]){box(entrance,.35,4.6,.35,'#94714f',x,2.3,0);for(let j=0;j<3;j++){const leaf=new T.Mesh(new T.IcosahedronGeometry(1.05,1),mat(route.id==='garden'?'#62865c':'#8d9871'));leaf.position.set(x,2.5+j*.85,0);entrance.add(leaf);}}box(entrance,6.6,.25,.4,'#987753',0,4.7,0);const sign=label('? ↗',2.8,.85,route.color,'#3b3b42',130);sign.position.set(0,4.55,-.24);sign.rotation.y=Math.PI;entrance.add(sign);
  for(let d=15;d<route.length-10;d+=13){const a=route.at(d),g=new T.Group();g.position.copy(a.p);g.rotation.y=Math.atan2(a.t.x,a.t.z);parent.add(g);if(route.id==='garden'){for(const side of [-1,1]){const trunk=box(g,.28,5,.28,'#84654c',side*3.8,2.5,0);const crown=new T.Mesh(new T.IcosahedronGeometry(2,1),mat('#ed9bbf'));crown.position.set(side*3.8,5.5,0);crown.castShadow=true;g.add(crown);}}else {for(const side of [-1,1]){box(g,1.6,4.7,8.5,'#cfae82',side*3.7,2.35,0);box(g,1.8,.24,9,'#edc899',side*3.7,4.8,0);}box(g,8.5,.26,2.5,'#e9be7f',0,5.2,0);}}
  const ramp=route.at(route.length*.57),g=new T.Group();g.position.copy(ramp.p);g.rotation.y=Math.atan2(ramp.t.x,ramp.t.z);parent.add(g);const rampMesh=box(g,route.width-.5,.22,3,route.color,0,.35,0);rampMesh.rotation.x=-.18;
 }
}
